DECLARE @bytes varbinary(max)=CONVERT(varbinary(max),CONVERT(varchar(max),@body COLLATE Latin1_General_100_BIN2_UTF8));
DECLARE @content binary(32)=HASHBYTES('SHA2_256',@bytes);
IF LOWER(CONVERT(varchar(64),@content,2))<>N'cf0f7bda1496ce137ad16cd4b22678a297357d539218bd2a7dd77f7ec3adb750' THROW 51000,N'DECLARED_CHANGE_CONTENT_DIVERGED',1;
IF NOT EXISTS(SELECT 1 FROM source.content_object WHERE content_digest=@content)
 INSERT source.content_object(content_digest,content_bytes,byte_length) VALUES(@content,@bytes,DATALENGTH(@bytes));
DECLARE @semantics nvarchar(max)=(SELECT JSON_QUERY(definition_json,'$.semantics') FROM analysis.v_selected_semantic_definition
 WHERE estate_model_pk=@estate AND object_kind='AUTHORITY' AND declared_id=N'sda-kernel-boot-data-access.v1');
SET @semantics=JSON_MODIFY(@semantics,'$.contentDigest',N'sha256:cf0f7bda1496ce137ad16cd4b22678a297357d539218bd2a7dd77f7ec3adb750');
DECLARE @object bigint,@definition bigint,@digest binary(32);
EXEC model.put_semantic_definition 'AUTHORITY',N'sidefx:authorities',N'sda-kernel-boot-data-access.v1',@semantics,@object OUTPUT,@definition OUTPUT,@digest OUTPUT;
SELECT N'declared_change_family' AS result_set,N'sha256:cf0f7bda1496ce137ad16cd4b22678a297357d539218bd2a7dd77f7ec3adb750' AS content_digest,N'provider-binding,scenario-registration' AS admitted_kinds;
COMMIT TRANSACTION;
